import { COLUMNS } from '../config';
import { unwrap, type Row, type TabularService } from './generated';
import type {
  CurrentUser,
  MailChanges,
  MailItem,
  MailKind,
  MailQuery,
  MailRepository,
  MailStatus,
  NewMailInput,
  Person,
} from './types';

/**
 * Stores deliveries in one SharePoint list through the service generated by
 * `pa app add data-source --connector "shared_sharepointonline" ...`.
 * Every column is plain text or a date, so values travel as simple strings.
 */
export class SharePointRepository implements MailRepository {
  readonly mode = 'sharepoint' as const;
  private readonly service: TabularService;

  constructor(service: TabularService) {
    this.service = service;
  }

  async list(query: MailQuery, top: number): Promise<MailItem[]> {
    const clauses = [`${COLUMNS.unit} eq '${odata(query.unit)}'`];
    if (query.kind) clauses.push(`${COLUMNS.kind} eq '${query.kind}'`);
    if (query.status) clauses.push(`${COLUMNS.status} eq '${query.status}'`);
    if (query.recipientEmail) clauses.push(`${COLUMNS.recipientEmail} eq '${odata(query.recipientEmail.toLowerCase())}'`);

    const rows = unwrap(
      await this.service.getAll({ filter: clauses.join(' and '), orderBy: [`${COLUMNS.created} desc`], top }),
      'Loading deliveries',
    );
    return (rows ?? []).map(toItem);
  }

  async create(input: NewMailInput, user: CurrentUser): Promise<MailItem> {
    const record: Row = {
      [COLUMNS.courierNumber]: input.courierNumber.trim(),
      [COLUMNS.kind]: input.kind,
      [COLUMNS.unit]: input.unit,
      [COLUMNS.courierCompany]: input.courierCompany.trim(),
      [COLUMNS.sender]: input.sender.trim(),
      [COLUMNS.recipientName]: input.recipientName.trim(),
      [COLUMNS.recipientEmail]: input.recipientEmail.trim().toLowerCase(),
      [COLUMNS.department]: input.department.trim(),
      [COLUMNS.status]: 'Waiting',
      [COLUMNS.loggedByName]: user.name,
      [COLUMNS.loggedByEmail]: user.email,
      [COLUMNS.notes]: input.notes.trim(),
    };
    const created = unwrap(await this.service.create(record), 'Logging the delivery');
    return toItem(created ?? { ...record, [COLUMNS.created]: new Date().toISOString() });
  }

  async update(id: string, changes: MailChanges): Promise<MailItem> {
    const current = await this.getOne(id);
    const record: Row = {};
    if (changes.courierNumber !== undefined) record[COLUMNS.courierNumber] = changes.courierNumber.trim();
    if (changes.courierCompany !== undefined) record[COLUMNS.courierCompany] = changes.courierCompany.trim();
    if (changes.sender !== undefined) record[COLUMNS.sender] = changes.sender.trim();
    if (changes.recipientName !== undefined) record[COLUMNS.recipientName] = changes.recipientName.trim();
    if (changes.recipientEmail !== undefined) record[COLUMNS.recipientEmail] = changes.recipientEmail.trim().toLowerCase();
    if (changes.department !== undefined) record[COLUMNS.department] = changes.department.trim();
    if (changes.notes !== undefined) record[COLUMNS.notes] = changes.notes.trim();
    return this.patch(id, current, record, 'Saving changes');
  }

  async collect(id: string, collector: Person): Promise<MailItem> {
    // Re-read first so two people can't confirm the same delivery.
    const current = await this.getOne(id);
    if (current.status !== 'Waiting') {
      throw new Error(`Already collected by ${current.collectedByName || 'someone else'}.`);
    }
    return this.patch(
      id,
      current,
      {
        [COLUMNS.status]: 'Collected',
        [COLUMNS.collectedByName]: collector.name,
        [COLUMNS.collectedByEmail]: collector.email.toLowerCase(),
        [COLUMNS.collectedOn]: new Date().toISOString(),
      },
      'Confirming collection',
    );
  }

  async reopen(id: string): Promise<MailItem> {
    const current = await this.getOne(id);
    return this.patch(
      id,
      current,
      {
        [COLUMNS.status]: 'Waiting',
        [COLUMNS.collectedByName]: '',
        [COLUMNS.collectedByEmail]: '',
        [COLUMNS.collectedOn]: null,
      },
      'Reopening the delivery',
    );
  }

  private async getOne(id: string): Promise<MailItem> {
    const row = unwrap(await this.service.get(id), 'Loading the delivery');
    if (!row) throw new Error('This delivery no longer exists.');
    return toItem(row);
  }

  private async patch(id: string, current: MailItem, record: Row, action: string): Promise<MailItem> {
    const updated = unwrap(await this.service.update(id, record), action);
    // Some connector versions return no body on update; merge locally instead.
    if (updated) return toItem(updated);
    return toItem({ ...fromItem(current), ...record, [COLUMNS.modified]: new Date().toISOString() });
  }
}

function odata(value: string): string {
  return value.trim().replace(/'/g, "''");
}

/** Reads a column as text; tolerates Choice `{ Value }` and Person `{ DisplayName, Email }` objects. */
function text(row: Row, column: string): string {
  const value = row[column];
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (typeof value === 'object') {
    const v = value as Record<string, unknown>;
    for (const key of ['Value', 'DisplayName', 'Email']) {
      if (typeof v[key] === 'string') return v[key] as string;
    }
  }
  return '';
}

function toItem(row: Row): MailItem {
  const kind = text(row, COLUMNS.kind);
  const status = text(row, COLUMNS.status);
  const created = text(row, COLUMNS.created) || new Date().toISOString();
  return {
    id: text(row, COLUMNS.id) || text(row, 'Id'),
    kind: (kind === 'Department' ? 'Department' : 'Personal') as MailKind,
    unit: text(row, COLUMNS.unit),
    courierNumber: text(row, COLUMNS.courierNumber),
    courierCompany: text(row, COLUMNS.courierCompany),
    sender: text(row, COLUMNS.sender),
    recipientName: text(row, COLUMNS.recipientName),
    recipientEmail: text(row, COLUMNS.recipientEmail).toLowerCase(),
    department: text(row, COLUMNS.department),
    status: (status === 'Collected' ? 'Collected' : 'Waiting') as MailStatus,
    collectedByName: text(row, COLUMNS.collectedByName),
    collectedByEmail: text(row, COLUMNS.collectedByEmail).toLowerCase(),
    collectedOn: text(row, COLUMNS.collectedOn) || null,
    loggedByName: text(row, COLUMNS.loggedByName),
    loggedByEmail: text(row, COLUMNS.loggedByEmail).toLowerCase(),
    notes: text(row, COLUMNS.notes),
    created,
    modified: text(row, COLUMNS.modified) || created,
  };
}

function fromItem(item: MailItem): Row {
  return {
    [COLUMNS.id]: item.id,
    [COLUMNS.courierNumber]: item.courierNumber,
    [COLUMNS.kind]: item.kind,
    [COLUMNS.unit]: item.unit,
    [COLUMNS.courierCompany]: item.courierCompany,
    [COLUMNS.sender]: item.sender,
    [COLUMNS.recipientName]: item.recipientName,
    [COLUMNS.recipientEmail]: item.recipientEmail,
    [COLUMNS.department]: item.department,
    [COLUMNS.status]: item.status,
    [COLUMNS.collectedByName]: item.collectedByName,
    [COLUMNS.collectedByEmail]: item.collectedByEmail,
    [COLUMNS.collectedOn]: item.collectedOn,
    [COLUMNS.loggedByName]: item.loggedByName,
    [COLUMNS.loggedByEmail]: item.loggedByEmail,
    [COLUMNS.notes]: item.notes,
    [COLUMNS.created]: item.created,
    [COLUMNS.modified]: item.modified,
  };
}
